import { getStore } from "@/lib/server/store"
import { getContent } from "@/lib/server/content"
import { chunkText, collectTexts, decodeEntities, protectTerms, restoreTerms, type Dictionary } from "@/lib/translate"

/**
 * MyMemory client + persistent cache. https://mymemory.translated.net/doc/spec.php
 * Anonymous use: ~5,000 chars/day. Set MYMEMORY_EMAIL to raise it to ~50,000 chars/day.
 * Translations are stored once (shared by all visitors), so quota is only spent on NEW or EDITED English text.
 */

const CACHE_KEY = "i18n:id"
const BLOCK_KEY = "i18n:blocked"
const CACHE_LIMIT = 4000
const BLOCK_MS = 60 * 60 * 1000
const ENDPOINT = "https://api.mymemory.translated.net/get"

export class QuotaError extends Error {}

export async function getTranslations(): Promise<Dictionary> {
  try {
    const raw = await getStore().get(CACHE_KEY)
    const parsed = raw ? (JSON.parse(raw) as unknown) : null
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? (parsed as Dictionary) : {}
  } catch { return {} }
}

async function saveTranslations(dict: Dictionary) {
  const keys = Object.keys(dict)
  const trimmed = keys.length > CACHE_LIMIT ? Object.fromEntries(keys.slice(keys.length - CACHE_LIMIT).map((key) => [key, dict[key]])) : dict
  await getStore().set(CACHE_KEY, JSON.stringify(trimmed))
}

export async function isBlocked(): Promise<boolean> {
  try {
    const until = Number(await getStore().get(BLOCK_KEY))
    return Number.isFinite(until) && until > Date.now()
  } catch { return false }
}
async function block() { try { await getStore().set(BLOCK_KEY, String(Date.now() + BLOCK_MS)) } catch { /* best effort */ } }

/** One chunk through MyMemory. Throws QuotaError when the daily quota is used up, Error for anything else. */
export async function translateChunk(text: string, fetcher: typeof fetch = fetch): Promise<string> {
  const params = new URLSearchParams({ q: text, langpair: "en|id" })
  const email = process.env.MYMEMORY_EMAIL
  if (email) params.set("de", email)
  const response = await fetcher(`${ENDPOINT}?${params}`, { headers: { Accept: "application/json" }, signal: AbortSignal.timeout(8000), cache: "no-store" })
  if (response.status === 429) throw new QuotaError("MyMemory quota reached")
  if (!response.ok) throw new Error(`MyMemory failed (${response.status})`)
  const data = (await response.json()) as { responseStatus?: number | string; responseData?: { translatedText?: string } }
  const translated = data.responseData?.translatedText
  if (Number(data.responseStatus) === 429 || (typeof translated === "string" && /^MYMEMORY WARNING/i.test(translated))) throw new QuotaError("MyMemory quota reached")
  if (Number(data.responseStatus) !== 200 || typeof translated !== "string" || !translated.trim()) throw new Error("MyMemory returned no translation")
  if (/^(PLEASE SELECT|INVALID)/i.test(translated)) throw new Error(translated.slice(0, 80))
  return decodeEntities(translated).trim()
}

/** A whole text (any length, protected terms kept as they are). */
export async function translateText(text: string, fetcher: typeof fetch = fetch): Promise<string> {
  const run = async (source: string) => {
    const parts: string[] = []
    for (const chunk of chunkText(source)) parts.push(await translateChunk(chunk, fetcher))
    return parts.join(" ")
  }
  const { text: protectedText, terms } = protectTerms(text)
  if (terms.length) {
    const restored = restoreTerms(await run(protectedText), terms)
    if (restored !== null) return restored
  }
  return run(text)
}

export interface TranslateResult {
  /** hash -> translation, for the requested hashes that are available now. */
  translations: Dictionary
  /** Texts of the site that still have no translation. */
  pending: number
  /** True while the MyMemory quota is exhausted (retry later). */
  blocked: boolean
}

export const MAX_PER_CALL = 24
const TIME_BUDGET_MS = 8000

/**
 * Translates up to MAX_PER_CALL missing texts of the site. Only text that actually exists in the site content is
 * ever sent to MyMemory, so this cannot be abused as a free translation proxy.
 * `wanted` limits the work to specific hashes (visitors); omit it to translate anything missing (admin warm-up).
 */
export async function translateMissing(wanted?: string[], fetcher: typeof fetch = fetch): Promise<TranslateResult> {
  const texts = collectTexts(await getContent())
  const cache = await getTranslations()
  const wantedSet = wanted ? new Set(wanted) : null
  const translations: Dictionary = {}
  for (const hash of wantedSet ?? texts.keys()) if (cache[hash] && texts.has(hash)) translations[hash] = cache[hash]

  const todo = [...texts].filter(([hash]) => !cache[hash] && (!wantedSet || wantedSet.has(hash)))
  let blocked = await isBlocked()
  let changed = false

  if (!blocked && todo.length) {
    const started = Date.now()
    const queue = todo.slice(0, MAX_PER_CALL)
    const worker = async () => {
      for (let next = queue.shift(); next && !blocked && Date.now() - started < TIME_BUDGET_MS; next = queue.shift()) {
        const [hash, source] = next
        try {
          const done = await translateText(source, fetcher)
          cache[hash] = done
          translations[hash] = done
          changed = true
        } catch (error) {
          if (error instanceof QuotaError) { blocked = true; await block() }
          // any other failure: leave this text for the next attempt
        }
      }
    }
    await Promise.all([worker(), worker(), worker()])
  }
  if (changed) await saveTranslations(cache)

  let pending = 0
  for (const hash of texts.keys()) if (!cache[hash]) pending++
  return { translations, pending, blocked }
}

